select
id, resume_id, file_name, file_type, file_size, storage_path, download_url, preview_url, md5, upload_time,
update_time
from resume_file


        and id = #{id}


        and resume_id = #{resumeId}


        and file_name = #{fileName}


        and file_type = #{fileType}


        and file_size = #{fileSize}


        and storage_path = #{storagePath}


        and download_url = #{downloadUrl}


        and preview_url = #{previewUrl}


        and md5 = #{md5}


        and upload_time = #{uploadTime}


        and update_time = #{updateTime}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from resume_file


        and id = #{id}


        and resume_id = #{resumeId}


        and file_name = #{fileName}


        and file_type = #{fileType}


        and file_size = #{fileSize}


        and storage_path = #{storagePath}


        and download_url = #{downloadUrl}


        and preview_url = #{previewUrl}


        and md5 = #{md5}


        and upload_time = #{uploadTime}


        and update_time = #{updateTime}
